#!/usr/bin/env bash\nset -euo pipefail\n\nPR_TITLE=\"$1\"\nLABEL_MAP_JSON=\"$2\"\n\n# Convert JSON mapping to a Bash associative array using Python (no external jq)\ndeclare -A MAP\nif [[ -n \"$LABEL_MAP_JSON\" && \"$LABEL_MAP_JSON\" != \"{}\" ]]; then\n  while IFS=\"=\" read -r key val; do\n    MAP[\"$key\"]=\"$val\"\n  done < <(python - <<PY\nimport sys, json\ndata = json.loads(sys.argv[1])\nfor k, v in data.items():\n    print(f\"{k}={v}\")\nPY\n \"$LABEL_MAP_JSON\")\nfi\n\n# Find matching labels based on keyword presence (case‑insensitive)\nOUTPUT_LABELS=()\nlower_title=$(echo \"$PR_TITLE\" | tr '[:upper:]' '[:lower:]')\nfor kw in "${!MAP[@]}"; do\n  if [[ \"$lower_title\" == *\"$kw\"* ]]; then\n    OUTPUT_LABELS+=(\"${MAP[$kw]}\")\n  fi\n done\n\n# Add a deterministic random emoji label (uses $RANDOM)\nEMOJIS=(\"🚀\" \"🐛\" \"✨\" \"🛠️\" \"📚\")\nRANDOM_INDEX=$((RANDOM % ${#EMOJIS[@]}))\nOUTPUT_LABELS+=(\"${EMOJIS[$RANDOM_INDEX]}\")\n\n# Print each label on its own line\nfor lbl in "${OUTPUT_LABELS[@]}"; do\n  echo \"$lbl\"\n done\n
